            run(mysql+['-e','CREATE DATABASE `'+testdb+'` CHARACTER SET utf8mb4']);created=True
            statements=[]
            for table in tables:
                if not re.fullmatch(r'[A-Za-z0-9_]+',table):raise RuntimeError('Invalid table identifier.')
                if table=='final_giveaway_rehearsal':continue
                statements.append('CREATE TABLE `'+testdb+'`.`'+table+'` LIKE `'+db+'`.`'+table+'`;')
